CREATE OR REPLACE FUNCTION public.has_accepted_terms(check_session_id text DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.terms_acceptance WHERE user_id = auth.uid()); $$;
CREATE OR REPLACE FUNCTION public.record_terms_acceptance(p_session_id text DEFAULT NULL, p_ip_address text DEFAULT NULL, p_user_agent text DEFAULT NULL, p_referer text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE record_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE = '42501'; END IF; SELECT id INTO record_id FROM public.terms_acceptance WHERE user_id = auth.uid() ORDER BY accepted_at DESC LIMIT 1; IF record_id IS NOT NULL THEN RETURN record_id; END IF; INSERT INTO public.terms_acceptance(user_id, session_id, user_agent, referer) VALUES(auth.uid(), NULL, left(p_user_agent,500), left(p_referer,500)) RETURNING id INTO record_id; INSERT INTO public.enhanced_security_logs(user_id,action_type,resource_type,resource_id,risk_level,metadata) VALUES(auth.uid(),'terms_acceptance','legal_agreement',record_id,'medium',jsonb_build_object('source','database')); RETURN record_id; END; $$;
REVOKE ALL ON FUNCTION public.record_terms_acceptance(text,text,text,text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.record_terms_acceptance(text,text,text,text) TO authenticated;
DROP POLICY IF EXISTS "Authenticated users can record terms acceptance" ON public.terms_acceptance;
REVOKE INSERT, UPDATE, DELETE ON public.terms_acceptance FROM anon, authenticated;
GRANT SELECT ON public.terms_acceptance TO authenticated;
GRANT ALL ON public.terms_acceptance TO service_role;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT (auth.role() = 'service_role' OR _user_id = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles caller WHERE caller.user_id=auth.uid() AND caller.role IN ('admin','super_admin') AND caller.is_active AND (caller.expires_at IS NULL OR caller.expires_at>now()))) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role::text=_role AND is_active AND (expires_at IS NULL OR expires_at>now())); $$;
CREATE OR REPLACE FUNCTION public.get_user_roles(check_user_id uuid DEFAULT auth.uid()) RETURNS TABLE(role public.user_role,is_active boolean,expires_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT ur.role,ur.is_active,ur.expires_at FROM public.user_roles ur WHERE ur.user_id=check_user_id AND ur.is_active AND (ur.expires_at IS NULL OR ur.expires_at>now()) AND (auth.role()='service_role' OR check_user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles caller WHERE caller.user_id=auth.uid() AND caller.role IN ('admin','super_admin') AND caller.is_active AND (caller.expires_at IS NULL OR caller.expires_at>now()))); $$;
CREATE OR REPLACE FUNCTION public.has_permission(check_permission public.permission,check_user_id uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT (auth.role()='service_role' OR check_user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles caller WHERE caller.user_id=auth.uid() AND caller.role IN ('admin','super_admin') AND caller.is_active AND (caller.expires_at IS NULL OR caller.expires_at>now()))) AND EXISTS(SELECT 1 FROM public.user_roles ur JOIN public.role_permissions rp ON ur.role=rp.role WHERE ur.user_id=check_user_id AND rp.permission=check_permission AND ur.is_active AND (ur.expires_at IS NULL OR ur.expires_at>now())); $$;
CREATE OR REPLACE FUNCTION public.is_admin_user(check_user_id uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT (auth.role()='service_role' OR check_user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles caller WHERE caller.user_id=auth.uid() AND caller.role IN ('admin','super_admin') AND caller.is_active AND (caller.expires_at IS NULL OR caller.expires_at>now()))) AND EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=check_user_id AND ur.role IN ('admin','super_admin') AND ur.is_active AND (ur.expires_at IS NULL OR ur.expires_at>now())); $$;
CREATE OR REPLACE FUNCTION public.is_super_admin_user(check_user_id uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT (auth.role()='service_role' OR check_user_id=auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles caller WHERE caller.user_id=auth.uid() AND caller.role IN ('admin','super_admin') AND caller.is_active AND (caller.expires_at IS NULL OR caller.expires_at>now()))) AND EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=check_user_id AND ur.role='super_admin' AND ur.is_active AND (ur.expires_at IS NULL OR ur.expires_at>now())); $$;
CREATE OR REPLACE FUNCTION public.get_current_user_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT ur.role::text FROM public.user_roles ur WHERE ur.user_id=auth.uid() AND ur.is_active AND (ur.expires_at IS NULL OR ur.expires_at>now()) ORDER BY CASE ur.role WHEN 'super_admin' THEN 1 WHEN 'admin' THEN 2 WHEN 'employee' THEN 3 ELSE 4 END LIMIT 1; $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,text), public.get_user_roles(uuid), public.has_permission(public.permission,uuid), public.is_admin_user(uuid), public.is_super_admin_user(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,text), public.get_user_roles(uuid), public.has_permission(public.permission,uuid), public.is_admin_user(uuid), public.is_super_admin_user(uuid) TO authenticated,service_role;
DROP POLICY IF EXISTS "Authenticated system can insert security logs" ON public.enhanced_security_logs;
DROP POLICY IF EXISTS "Users can insert their own security logs" ON public.enhanced_security_logs;
REVOKE INSERT,UPDATE,DELETE ON public.enhanced_security_logs FROM anon,authenticated;
GRANT SELECT ON public.enhanced_security_logs TO authenticated;
GRANT ALL ON public.enhanced_security_logs TO service_role;
CREATE OR REPLACE FUNCTION public.record_client_security_event(p_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF; IF p_action IS NULL OR p_action NOT IN ('login_successful','login_failed','login_error','signup_failed','signup_successful','signup_error','logout','password_change_failed','password_changed','rate_limit_exceeded','config_updated','admin_session_backgrounded','admin_devtools_detected','session_hijack_attempt') THEN RAISE EXCEPTION 'Invalid event' USING ERRCODE='22023'; END IF; INSERT INTO public.enhanced_security_logs(user_id,action_type,resource_type,risk_level,metadata) VALUES(auth.uid(),'client_reported_'||p_action,'client_telemetry','low',jsonb_build_object('source','untrusted_client')); END; $$;
REVOKE ALL ON FUNCTION public.record_client_security_event(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.record_client_security_event(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.audit_admin_work_session_adjustment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF public.is_admin_user() AND (OLD.clock_in_time IS DISTINCT FROM NEW.clock_in_time OR OLD.clock_out_time IS DISTINCT FROM NEW.clock_out_time OR OLD.status IS DISTINCT FROM NEW.status OR OLD.notes IS DISTINCT FROM NEW.notes) THEN INSERT INTO public.enhanced_security_logs(user_id,action_type,resource_type,resource_id,old_values,new_values,risk_level,metadata) VALUES(auth.uid(),'work_session_adjustment','work_sessions',NEW.id,jsonb_build_object('clock_in_time',OLD.clock_in_time,'clock_out_time',OLD.clock_out_time,'status',OLD.status,'total_hours',OLD.total_hours),jsonb_build_object('clock_in_time',NEW.clock_in_time,'clock_out_time',NEW.clock_out_time,'status',NEW.status,'total_hours',NEW.total_hours),'medium',jsonb_build_object('source','database','employee_id',NEW.employee_id)); END IF; RETURN NEW; END; $$;
CREATE TRIGGER audit_admin_work_session_adjustment AFTER UPDATE ON public.work_sessions FOR EACH ROW EXECUTE FUNCTION public.audit_admin_work_session_adjustment();
ALTER TABLE public.abandoned_quotes ADD COLUMN email_verified boolean NOT NULL DEFAULT false;
DROP POLICY IF EXISTS "Authenticated users can view active services" ON public.services;
CREATE POLICY "NDA accepted users can view active services" ON public.services FOR SELECT TO authenticated USING(is_active AND public.has_accepted_terms());